function [c, d] = a2b3(a, b):
% 函数定义保存在 a2b3.m 文件中
function [c, d] = a2b3(a, b)
    c = a * 2;
    d = b * 3;
end

function [c, d] = a4b5(a, b):
% 函数定义保存在 a4b5.m 文件中
function [c, d] = a4b5(a, b)
    c = a4(a);
    d = b5(b);
end

function c = a4(a)
    c = a * 4;
end

function d = b5(b)
    d = b * 5;
end

